import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [items, setItems] = useState(['Apple', 'Banana']);
  const [input, setInput] = useState('');

  const addItem = () => {
    if (input.trim()) {
      items.push(input.trim());
      setItems(items);
      setInput('');
    }
  };

  return (
    <div>
      <div>
        <input
          id="item-input"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Add a fruit..."
        />
        <button id="add-btn" onClick={addItem}>Add Item</button>
      </div>
      <ul id="item-list">
        {items.map((item, i) => (
          <li key={i}>{item}</li>
        ))}
      </ul>
      <span id="count">{items.length} items</span>
    </div>
  );
}

export default App;

