import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Mutant Array', () => {
  test('Renders initial 2 items', async () => {
    const { container: root } = render(<App />);
    const items = root.querySelectorAll('#item-list li');
if (items.length !== 2) throw new Error('Expected 2 initial items');
  });

  test('Adding an item updates the list', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#item-input');
const btn = root.querySelector('#add-btn');
const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
nativeSetter.call(input, 'Cherry');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
const items = root.querySelectorAll('#item-list li');
if (items.length !== 3) throw new Error('Expected 3 items after adding, got ' + items.length);
  });

  test('Count updates after adding', async () => {
    const { container: root } = render(<App />);
    const count = root.querySelector('#count');
if (!count.textContent.includes('3')) throw new Error('Count should show 3');
  });

  test('Input clears after adding', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#item-input');
if (input.value !== '') throw new Error('Input should clear after adding');
  });
});
